css:
.aha-hero-section{
  --aha-hero-section-surface:var(--aha-white);
  --aha-hero-section-ink:var(--aha-text-default);
  --aha-hero-section-ink-secondary:var(--aha-text-secondary);
  --aha-hero-section-eyebrow:var(--aha-color-primary);
  --aha-hero-section-frame:var(--aha-border-default);
  --aha-hero-section-media-bg:var(--aha-bg-container-secondary);
  --aha-hero-section-focus:var(--aha-focus);
  container:aha-hero-section / inline-size;
  position:relative;overflow:hidden;
  font-family:var(--aha-font-product);
  background:var(--aha-hero-section-surface);
  color:var(--aha-hero-section-ink);
}
.aha-hero-section--brand,.aha-hero-section__panel--brand{
  --aha-hero-section-surface:var(--aha-vivid-pink-100);
  --aha-hero-section-ink:var(--aha-text-inverse);
  --aha-hero-section-ink-secondary:var(--aha-text-inverse);
  --aha-hero-section-eyebrow:var(--aha-text-inverse);
  --aha-hero-section-frame:var(--aha-vivid-pink-dark);
  --aha-hero-section-focus:var(--aha-white);
}
.aha-hero-section *{box-sizing:border-box}
:where(.aha-hero-section) :is(h1,h2,p,ul,form,figure){margin:0;padding:0}
:where(.aha-hero-section) ul{list-style:none}
.aha-hero-section__inner{max-width:1280px;margin:0 auto;padding:var(--aha-space-96) var(--aha-space-32)}
.aha-hero-section__split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--aha-space-64);align-items:center}
.aha-hero-section__copy{display:flex;flex-direction:column;align-items:flex-start;max-width:640px}
.aha-hero-section__eyebrow{
  margin-bottom:var(--aha-space-16);
  font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;
  color:var(--aha-hero-section-eyebrow);
}
.aha-hero-section__badge{
  display:inline-flex;align-items:center;margin-bottom:var(--aha-space-24);padding:var(--aha-space-4) var(--aha-space-12);
  border:1px solid var(--aha-hero-section-frame);border-radius:var(--aha-radius-pill);
  font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);
  color:var(--aha-hero-section-ink);
}
.aha-hero-section__title{
  font-size:var(--aha-size-h1);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-hero-section-ink);
}
.aha-hero-section__text{
  margin-top:var(--aha-space-24);
  font-size:var(--aha-size-xl);font-weight:var(--aha-weight-regular);line-height:var(--aha-line-height-body);
  letter-spacing:var(--aha-letter-spacing-paragraph);
  color:var(--aha-hero-section-ink-secondary);
}
.aha-hero-section__actions{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);margin-top:var(--aha-space-40)}
.aha-hero-section__button{
  display:inline-flex;align-items:center;justify-content:center;
  height:var(--aha-control-height-button-xl);padding:0 var(--aha-space-20);
  border:1px solid transparent;border-radius:var(--aha-radius-default);
  font-family:inherit;font-size:var(--aha-size-h6);font-weight:var(--aha-weight-regular);line-height:1;white-space:nowrap;
  text-decoration:none;cursor:pointer;
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out),border-color var(--aha-motion-mid) var(--aha-ease-in-out),color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-hero-section__button:focus-visible{outline:var(--aha-space-2) solid var(--aha-hero-section-focus);outline-offset:var(--aha-space-2)}
.aha-hero-section__button--primary{background:var(--aha-button-primary-bg);color:var(--aha-button-primary-text)}
.aha-hero-section__button--primary:hover,.aha-hero-section__button--primary:active{background:var(--aha-button-primary-bg-hover)}
.aha-hero-section__button--secondary{background:var(--aha-button-default-bg);border-color:var(--aha-button-default-border);color:var(--aha-button-default-text)}
.aha-hero-section__button--secondary:hover,.aha-hero-section__button--secondary:active{background:var(--aha-button-default-bg-hover);border-color:var(--aha-button-default-border-hover);color:var(--aha-button-default-text-hover)}
:is(.aha-hero-section--brand,.aha-hero-section__panel--brand) .aha-hero-section__button--primary{background:var(--aha-white);color:var(--aha-color-primary);box-shadow:var(--aha-button-elevate-primary)}
:is(.aha-hero-section--brand,.aha-hero-section__panel--brand) .aha-hero-section__button--primary:hover,:is(.aha-hero-section--brand,.aha-hero-section__panel--brand) .aha-hero-section__button--primary:active{background:var(--aha-white);color:var(--aha-color-primary-hover);box-shadow:var(--aha-button-elevate-primary-hover)}
:is(.aha-hero-section--brand,.aha-hero-section__panel--brand) .aha-hero-section__button--secondary{background:transparent;border-color:var(--aha-white);color:var(--aha-text-inverse)}
:is(.aha-hero-section--brand,.aha-hero-section__panel--brand) .aha-hero-section__button--secondary:hover,:is(.aha-hero-section--brand,.aha-hero-section__panel--brand) .aha-hero-section__button--secondary:active{background:var(--aha-vivid-pink-dark);border-color:var(--aha-white);color:var(--aha-text-inverse)}
.aha-hero-section__form{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);width:100%;max-width:480px;margin-top:var(--aha-space-40)}
.aha-hero-section__field{display:flex;flex:1 1 240px;min-width:0}
.aha-hero-section__input{
  width:100%;height:var(--aha-control-height-button-xl);padding:0 var(--aha-space-16);
  border:1px solid var(--aha-border-input);border-radius:var(--aha-radius-default);
  background:var(--aha-white);color:var(--aha-text-default);
  font-family:inherit;font-size:var(--aha-size-l);
  transition:border-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-hero-section__input::placeholder{color:var(--aha-text-placeholder);opacity:1}
.aha-hero-section__input:hover{border-color:var(--aha-border-hover)}
.aha-hero-section__input:focus{outline:none;border-color:var(--aha-border-focus)}
.aha-hero-section__input:focus-visible{outline:var(--aha-space-2) solid var(--aha-hero-section-focus);outline-offset:var(--aha-space-2)}
.aha-hero-section__hint{margin-top:var(--aha-space-12);font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-hero-section-ink-secondary)}
.aha-hero-section__checks{display:flex;flex-direction:column;gap:var(--aha-space-12);margin-top:var(--aha-space-32)}
.aha-hero-section__check{display:flex;align-items:center;gap:var(--aha-space-12);font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-hero-section-ink)}
.aha-hero-section__check aha-icon{flex:none;color:var(--aha-color-primary)}
:is(.aha-hero-section--brand,.aha-hero-section__panel--brand) .aha-hero-section__check aha-icon{color:var(--aha-white)}
.aha-hero-section__media{display:block;min-width:0}
.aha-hero-section__image{
  display:block;width:100%;height:auto;object-fit:cover;
  border-radius:var(--aha-radius-xl);background:var(--aha-hero-section-media-bg);
}
.aha-hero-section__centred{display:flex;flex-direction:column;align-items:center}
.aha-hero-section__centred .aha-hero-section__copy{align-items:center;max-width:768px;text-align:center}
.aha-hero-section__centred .aha-hero-section__actions{justify-content:center}
.aha-hero-section__centred .aha-hero-section__media{width:100%;margin-top:var(--aha-space-64)}
.aha-hero-section__card{
  width:100%;padding:var(--aha-space-32);
  border:1px solid var(--aha-hero-section-frame);border-radius:var(--aha-radius-xl);background:var(--aha-white);
}
.aha-hero-section__card-title{font-size:var(--aha-size-h4);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);color:var(--aha-text-default)}
.aha-hero-section__card-text{margin-top:var(--aha-space-8);font-size:var(--aha-size-l);line-height:var(--aha-line-height-body);color:var(--aha-text-secondary)}
.aha-hero-section__card-form{display:flex;flex-direction:column;gap:var(--aha-space-16);margin-top:var(--aha-space-24)}
.aha-hero-section__label{display:flex;flex-direction:column;gap:var(--aha-space-6);font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);color:var(--aha-text-default)}
.aha-hero-section__card-form .aha-hero-section__button{width:100%}
.aha-hero-section__card-note{margin-top:var(--aha-space-16);font-size:var(--aha-size-default);text-align:center;color:var(--aha-text-secondary)}
.aha-hero-section__card-note a{color:var(--aha-color-primary);text-decoration:none}
.aha-hero-section__card-note a:hover{text-decoration:underline}
@container aha-hero-section (max-width:991px){
  .aha-hero-section__inner{padding:var(--aha-space-64) var(--aha-space-32)}
  .aha-hero-section__split{grid-template-columns:minmax(0,1fr);gap:var(--aha-space-48)}
  .aha-hero-section__title{font-size:var(--aha-size-h3)}
  .aha-hero-section__text{font-size:var(--aha-size-l)}
}
@container aha-hero-section (max-width:479px){
  .aha-hero-section__inner{padding:var(--aha-space-48) var(--aha-space-24)}
  .aha-hero-section__title{font-size:var(--aha-size-h4)}
  .aha-hero-section__actions{width:100%}
  .aha-hero-section__actions .aha-hero-section__button,.aha-hero-section__form .aha-hero-section__button{flex:1 1 100%}
  .aha-hero-section__card{padding:var(--aha-space-24)}
}
.aha-hero-section__visually-hidden{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.aha-hero-section--split-image-03 .aha-hero-section__image{aspect-ratio:5 / 4}
